use std::collections::HashMap;
use std::env;

#[derive(Clone, Debug)]
struct Account {
    balance: u64,
    withdrawal_limit: u64,
    is_frozen: bool,
    failed_attempts: u32,
}

struct Bank {
    accounts: HashMap<String, Account>,
    audit_log: Vec<String>,
}

impl Bank {
    fn new() -> Self {
        let mut accounts = HashMap::new();
        accounts.insert("alice".to_string(), Account {
            balance: 1_000_000,
            withdrawal_limit: 50_000,
            is_frozen: false,
            failed_attempts: 0,
        });
        accounts.insert("bob".to_string(), Account {
            balance: 500,
            withdrawal_limit: 200,
            is_frozen: false,
            failed_attempts: 0,
        });
        Bank { accounts, audit_log: Vec::new() }
    }

    /// Computes the available balance after reserving minimum_reserve.
    /// Returns error if balance is below the reserve requirement.
    fn available_balance(&self, account: &Account, minimum_reserve: u64) -> Result<u64, String> {
        if account.balance < minimum_reserve {
            return Err("Balance below minimum reserve".to_string());
        }
        Ok(account.balance - minimum_reserve)
    }

    /// Validates that a withdrawal amount is within policy limits.
    /// Returns the effective withdrawal cap for this transaction.
    fn compute_withdrawal_cap(&self, account: &Account, requested: u64) -> u64 {
        let limit = account.withdrawal_limit;
        // Cap at the withdrawal limit
        if requested > limit {
            limit
        } else {
            requested
        }
    }

    /// Core authorization: checks if withdrawal should be permitted.
    /// Requires: account not frozen, amount within limit, sufficient available balance.
    fn authorize_withdrawal(&self, username: &str, amount: u64, minimum_reserve: u64) -> Result<u64, String> {
        let account = self.accounts.get(username)
            .ok_or_else(|| "Account not found".to_string())?;

        if account.is_frozen {
            return Err("Account is frozen".to_string());
        }

        let effective_amount = self.compute_withdrawal_cap(account, amount);
        let available = self.available_balance(account, minimum_reserve)?;

        // Security check: ensure sufficient available funds
        if effective_amount <= available {
            Ok(effective_amount)
        } else {
            Err(format!("Insufficient available balance: {} available, {} requested",
                       available, effective_amount))
        }
    }

    /// Execute a withdrawal with overdraft protection.
    /// The minimum_reserve parameter is computed from account tier.
    fn process_withdrawal(&mut self, username: &str, amount: u64) -> Result<String, String> {
        // Compute minimum reserve based on account balance tier
        let minimum_reserve = {
            let account = self.accounts.get(username)
                .ok_or_else(|| "Account not found".to_string())?;
            self.compute_minimum_reserve(account)
        };

        let effective_amount = self.authorize_withdrawal(username, amount, minimum_reserve)?;

        // Perform the actual withdrawal
        let account = self.accounts.get_mut(username).unwrap();
        account.balance = account.balance.saturating_sub(effective_amount);

        let msg = format!("Withdrew {} from {} (reserve: {}, remaining: {})",
                         effective_amount, username, minimum_reserve, account.balance);
        self.audit_log.push(msg.clone());
        Ok(msg)
    }

    /// Determines minimum reserve based on account balance.
    /// Higher balances require higher reserves (tiered system).
    fn compute_minimum_reserve(&self, account: &Account) -> u64 {
        match account.balance {
            0..=999 => account.balance,           // Tier 1: reserve ALL funds (no withdrawals)
            1_000..=99_999 => 1_000,              // Tier 2: keep 1000 minimum
            100_000..=999_999 => 10_000,          // Tier 3: keep 10000 minimum
            _ => 50_000,                          // Tier 4: keep 50000 minimum
        }
    }

    /// Transfer between accounts with reserve enforcement on source.
    fn process_transfer(&mut self, from: &str, to: &str, amount: u64) -> Result<String, String> {
        if from == to {
            return Err("Cannot transfer to same account".to_string());
        }

        // Validate destination exists
        if !self.accounts.contains_key(to) {
            return Err("Destination account not found".to_string());
        }

        // Transfers also enforce minimum reserve
        let minimum_reserve = {
            let account = self.accounts.get(from)
                .ok_or_else(|| "Source account not found".to_string())?;
            self.compute_minimum_reserve(account)
        };

        let effective_amount = self.authorize_withdrawal(from, amount, minimum_reserve)?;

        let from_account = self.accounts.get_mut(from).unwrap();
        from_account.balance = from_account.balance.saturating_sub(effective_amount);

        let to_account = self.accounts.get_mut(to).unwrap();
        to_account.balance = to_account.balance.saturating_add(effective_amount);

        let msg = format!("Transferred {} from {} to {}", effective_amount, from, to);
        self.audit_log.push(msg.clone());
        Ok(msg)
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 4 {
        eprintln!("Usage: {} <operation> <username> <amount> [destination]", args[0]);
        eprintln!("Operations: withdraw, transfer");
        return;
    }

    let operation = &args[1];
    let username = &args[2];
    let amount: u64 = match args[3].parse() {
        Ok(v) => v,
        Err(_) => { eprintln!("Invalid amount"); return; }
    };

    let mut bank = Bank::new();

    let result = match operation.as_str() {
        "withdraw" => bank.process_withdrawal(username, amount),
        "transfer" => {
            if args.len() < 5 {
                Err("Transfer requires destination".to_string())
            } else {
                bank.process_transfer(username, &args[4], amount)
            }
        }
        _ => Err("Unknown operation".to_string()),
    };

    match result {
        Ok(msg) => println!("SUCCESS: {}", msg),
        Err(e) => println!("DENIED: {}", e),
    }
}
